 @JavascriptInterface public boolean saveGuestImage(String raw){if(raw==null||raw.length()>560000)return false;try{JSONObject item=new JSONObject(raw);String id=item.getString("id"),url=item.getString("dataUrl");if(!id.matches("[-a-zA-Z0-9_]{8,80}")||!url.matches("^data:image/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$"))return false;ContentValues values=new ContentValues();values.put("id",id);values.put("value",raw);database.insertWithOnConflict("device_media",null,values,SQLiteDatabase.CONFLICT_IGNORE);return true;}catch(Exception e){return false;}}
